# Create a figure and an axis
fig, ax = plt.subplots(figsize=(10, 2))

# Create a horizontal bar for each color
for idx, color in enumerate(colors_normalized):
    ax.add_patch(plt.Rectangle((idx, 0), 1, 1, color=color))

# Set the limits and remove axes for a clean look.
ax.set_xlim(0, len(colors_normalized))
ax.set_ylim(0, 1)
ax.set_xticks(np.arange(len(colors_normalized)) + 0.5)
ax.set_xticklabels([f"{i}" for i in range(len(colors_normalized))])
ax.set_yticks([])
ax.set_title("Interpolated Colors Over 24 Hours")

plt.tight_layout()
plt.show()
